<?php
namespace App\Services; use App\Mail\TrainingSessionInvitationMail; use App\Models\TrainingSession; use Illuminate\Support\Facades\Mail;
class TrainingInvitationService { public function send(TrainingSession$s,int$user,bool$reminder=false):array{$event=$s->attendanceEvent;abort_unless($event,422,'Primero debe congelar la población.');$sent=0;$failed=0;foreach($event->participants()->whereNull('excluded_at')->get() as$p){if(!$p->email)continue;try{Mail::to($p->email)->send(new TrainingSessionInvitationMail($s,$reminder));$p->update(['invitation_status'=>'sent','invited_at'=>now()]);$sent++;}catch(\Throwable$e){$p->update(['invitation_status'=>'failed']);$failed++;}}app(TrainingSessionService::class)->audit($s,$reminder?'training_reminder_sent':'training_invitation_sent',$user,['sent'=>$sent,'failed'=>$failed]);return compact('sent','failed');} }
